<header><div><h2>{{ $title }}</h2><p>Configure limits and the contribution calculation.</p></div><button type="button" data-member-modal-close><i class="fa-solid fa-xmark"></i></button></header>
<div class="reference-member-modal-body wagering-form"><label>Name<input name="name" value="{{ old('name',$policy?->name) }}" required></label><div class="wagering-form-grid"><label>Minimum Stake<input type="number" step="0.01" min="0" name="minimum_stake" value="{{ old('minimum_stake',$policy?->minimum_stake) }}" required></label><label>Minimum Deposit Amount<input type="number" step="0.01" min="0" name="minimum_deposit" value="{{ old('minimum_deposit',$policy?->minimum_deposit) }}" required></label><label>Maximum Contribution Amount<input type="number" step="0.01" min="0" name="maximum_contribution" value="{{ old('maximum_contribution',$policy?->maximum_contribution) }}" required></label><label>Contribution Type<select name="contribution_type"><option value="percentage" @selected(old('contribution_type',$policy?->contribution_type)==='percentage')>Percentage</option><option value="fixed_amount" @selected(old('contribution_type',$policy?->contribution_type)==='fixed_amount')>Fixed Amount</option></select></label><label>Contribution Percentage / Amount<input type="number" step="0.01" min="0" name="contribution_percentage" value="{{ old('contribution_percentage',$policy?->contribution_percentage ?? 100) }}" required></label></div></div>
<footer><button type="button" class="secondary" data-member-modal-close>Cancel</button><button type="submit">{{ $policy?'Save Changes':'Create' }}</button></footer>
